import{_ as a,o as s,c as i,al as t}from"./chunks/framework.7vp1BMOE.js";const k=JSON.parse('{"title":"Bootloader Secure Boot","description":"","frontmatter":{},"headers":[],"relativePath":"zh/advanced_config/bootloader_secure_boot.md","filePath":"zh/advanced_config/bootloader_secure_boot.md"}'),o={name:"zh/advanced_config/bootloader_secure_boot.md"};function n(r,e,l,d,p,h){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="bootloader-secure-boot" tabindex="-1">Bootloader Secure Boot <a class="header-anchor" href="#bootloader-secure-boot" aria-label="Permalink to &quot;Bootloader Secure Boot&quot;">​</a></h1><p>Secure boot is a feature that ensures that only cryptographically authorized PX4 firmware is executed. This is used by OEMs to ensure that only their validated, tested firmware runs on the vehicle — protecting safety, brand integrity, and regulatory compliance, and stopping others from running unauthorized software on their hardware.</p><p>The <em>PX4 Bootloader</em> can verify a cryptographic signature over the PX4 firmware before it is run. When enabled, only a firmware image signed with a private key whose matching public key is baked into the bootloader will boot. For any unsigned image, tampered image, or image signed by the wrong key, the device will wait in the bootloader screen (where it can be recovered safely over USB), and will not start the rest of the PX4 flight stack.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>This feature is intended for OEMs.</p><p>If you flash a bootloader that trusts a public key whose private counterpart you have lost, you can no longer sign new firmware for that device and will need a debug probe to recover it. Keep private keys backed up and never commit them to source control.</p></div><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><p>PX4&#39;s secure boot uses <a href="https://en.wikipedia.org/wiki/EdDSA#Ed25519" target="_blank" rel="noreferrer">ed25519</a> signatures (via <a href="https://monocypher.org" target="_blank" rel="noreferrer">monocypher</a>). The signing key is 32 bytes and the resulting signature is 64 bytes. Verification is fast (no random number generator is required on the device), and the implementation is small enough to fit in a 128 KB bootloader sector alongside the rest of the bootloader.</p><p>A signed firmware image lays out in flash like this:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>+---------------------------+  APP_LOAD_ADDRESS              ─┐</span></span>
<span class="line"><span>| Vector table              |                                 │</span></span>
<span class="line"><span>+---------------------------+  APP_LOAD_ADDRESS               │</span></span>
<span class="line"><span>| Image TOC                 |    + BOARD_IMAGE_TOC_OFFSET     │ BOOT region</span></span>
<span class="line"><span>+---------------------------+                                 │ (hashed and signed)</span></span>
<span class="line"><span>| .text / .rodata / .data   |                                 │</span></span>
<span class="line"><span>+---------------------------+  &amp;_boot_signature              ─┤</span></span>
<span class="line"><span>| 64-byte ed25519 signature |                                 │ SIG1</span></span>
<span class="line"><span>+---------------------------+                                ─┘</span></span></code></pre></div><p>The <strong>Table of Contents (TOC)</strong> is a small data structure compiled into the firmware that tells the bootloader which region to hash and which key slot to verify against. Its format is defined in <a href="https://github.com/PX4/PX4-Autopilot/blob/main/src/include/image_toc.h" target="_blank" rel="noreferrer"><code>src/include/image_toc.h</code></a>. For px4_fmu-v6x the TOC declares two entries: <strong>BOOT</strong> (the firmware bytes to verify) and <strong>SIG1</strong> (the 64-byte ed25519 signature to verify them against).</p><p>On reset the bootloader reads the TOC at a fixed offset, computes an ed25519 signature over the BOOT region, and compares it to the SIG1 entry. If the signature verifies it jumps to the app; otherwise it stays in the bootloader and waits for a new upload.</p><p>The host-side uploader (<code>Tools/px4_uploader.py</code>) also asks the bootloader to verify the signature before sending the final reboot, via a dedicated <code>VERIFY_SIG</code> opcode. This means a signature mismatch is reported as a clean error from <code>px_uploader.py</code> instead of a silent &quot;device stays in bootloader after reboot&quot;.</p><h2 id="trying-it-out" tabindex="-1">Trying It Out <a class="header-anchor" href="#trying-it-out" aria-label="Permalink to &quot;Trying It Out&quot;">​</a></h2><p>PX4 ships a secure-boot example for <strong>px4_fmu-v6x</strong>. This consists of two build variants:</p><ul><li><code>px4_fmu-v6x_bootloader_secureboot</code> — the secure bootloader, with ed25519 verification enabled, and the upstream <em>test public key</em> baked in.</li><li><code>px4_fmu-v6x_secureboot</code> — PX4 firmware, with TOC and automatic signing.</li></ul><p>步骤如下：</p><ol><li>Build and flash the secure bootloader (one-time, via SWD) <ul><li><p>Build the bootloader:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_fmu-v6x_bootloader_secureboot</span></span></code></pre></div></li><li><p>Flash the resulting <code>build/px4_fmu-v6x_bootloader_secureboot/px4_fmu-v6x_bootloader_secureboot.elf</code> via a debug probe. See <a href="./../advanced_config/bootloader_update">Bootloader Update</a>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>This is the only step that needs SWD — once the secure bootloader is in place, all firmware updates go over USB.</p></div></li></ul></li></ol><p>:::</p><ol start="2"><li><p>Build and upload signed firmware</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_fmu-v6x_secureboot</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upload</span></span></code></pre></div><p>The build produces an unsigned <code>.bin</code>, signs it with the upstream test key (<code>Tools/test_keys/test_keys.json</code>), wraps it in a <code>.px4</code> envelope marked <code>image_signed: true</code>, and uploads it. You will see something like:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Verify</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">   ▕██████████████████████████████▏</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 100%</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Verifying</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> image</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> signature...</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> passed</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Uploaded</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> in</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 18s</span></span></code></pre></div></li></ol><p>If you upload an image that the bootloader can&#39;t verify (e.g. an unsigned <code>.px4</code>, a tampered <code>.bin</code>, or one signed with a different key), <code>px_uploader.py</code> reports the failure before reboot:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Upload</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> failed:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Signature</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verification</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> failed:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> image</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> will</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> not</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boot.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">The</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bootloader</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> computed</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> a</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> signature</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> over</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> the</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> flashed</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> image</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> that</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> does</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> not</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">match</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> any</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> public</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> key</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> it</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> trusts.</span></span></code></pre></div><h2 id="generating-your-own-keys" tabindex="-1">Generating Your Own Keys <a class="header-anchor" href="#generating-your-own-keys" aria-label="Permalink to &quot;Generating Your Own Keys&quot;">​</a></h2><p>The default test key is committed to the PX4 tree, so a real deployment must replace it (in order to protect the public key). Generate a new ed25519 key pair with:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Tools/secure_bootloader/generate_signing_keys.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/my_key</span></span></code></pre></div><p>This writes:</p><ul><li><code>my_key.json</code> — the private key used by <code>sign_firmware.py</code>. <strong>Keep this private. Do not commit it.</strong></li><li><code>my_key.pub</code> — the public key as a C-array fragment, suitable for <code>#include</code> in the bootloader&#39;s keystore.</li></ul><p>Make the following changes use your new keys in the build:</p><ol><li><p><strong>Update the bootloader to trust your public key.</strong></p><p>Edit <code>boards/px4/fmu-v6x/bootloader_secureboot.px4board</code> and change <code>CONFIG_PUBLIC_KEY0</code> to point at <code>my_key.pub</code>. Rebuild and reflash the bootloader via SWD.</p></li><li><p><strong>Tell the app build to sign with the matching private key.</strong></p><p>Either edit <code>boards/px4/fmu-v6x/secureboot.px4board</code> and change <code>CONFIG_BOARD_SECUREBOOT_KEY</code> to point at <code>my_key.json</code>, or set the environment variable at build time:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">BOARD_SECUREBOOT_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/path/to/my_key.json</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_fmu-v6x_secureboot</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upload</span></span></code></pre></div></li></ol><p>The keys used must always be the corresponding cryptographic pair — if you flash a bootloader that trusts a key whose private half you don&#39;t have, you can only recover via SWD.</p><h2 id="enabling-secure-boot-on-a-new-board" tabindex="-1">Enabling Secure Boot on a New Board <a class="header-anchor" href="#enabling-secure-boot-on-a-new-board" aria-label="Permalink to &quot;Enabling Secure Boot on a New Board&quot;">​</a></h2><p>To enable secure boot up on a board that doesn&#39;t already have a <code>secureboot</code> variant, you&#39;ll need:</p><ul><li>a <code>toc.c</code> file placed in the board&#39;s <code>src/</code> (modeled on <code>boards/px4/fmu-v6x/src/toc.c</code>),</li><li>a linker script with <code>_main_toc</code> reserved at a fixed offset past the vector table and a <code>.signature</code> section at the end of FLASH (see <code>boards/px4/fmu-v6x/nuttx-config/scripts/secureboot-script.ld</code>)</li><li>a <code>secureboot.px4board</code> setting <code>CONFIG_BOARD_SECUREBOOT=y</code> and the linker prefix,</li><li>a <code>bootloader_secureboot.px4board</code> enabling <code>CONFIG_BOARD_CRYPTO</code>, <code>CONFIG_DRIVERS_SW_CRYPTO</code>, <code>CONFIG_DRIVERS_STUB_KEYSTORE</code> and the public-key path,</li><li><code>BOOTLOADER_USE_SECURITY</code> + <code>BOOTLOADER_SIGNING_ALGORITHM</code> + <code>BOARD_IMAGE_TOC_OFFSET</code> defines in the board&#39;s <code>hw_config.h</code>, gated on <code>PX4_CRYPTO</code>.</li></ul><p>The fmu-v6x variant files are kept small and self-contained for exactly this reason — they are intended to be copied as a starting point.</p><h2 id="另见" tabindex="-1">另见 <a class="header-anchor" href="#另见" aria-label="Permalink to &quot;另见&quot;">​</a></h2><ul><li><a href="./../advanced_config/bootloader_update">Bootloader 更新</a></li><li><a href="./../advanced_config/oem">OEM/Factory Configuration</a></li></ul>`,34)])])}const u=a(o,[["render",n]]);export{k as __pageData,u as default};
